Console.WriteLine(new List<List<string>>(){(await File.ReadAllLinesAsync("data.txt")).Select(t => t.Trim()).ToList()}.Select(l => l[..l.IndexOf("")].Select(t => t.Split("-")).Select(t => (long.Parse(t[0]), long.Parse(t[1])))).Select(l => l.OrderBy(t => t.Item1).ThenBy(t => t.Item2)).Select(l => l.Skip(1).Aggregate<(long,long),System.Collections.Immutable.ImmutableList<(long,long)>>([l.First()], (curr,it) => curr.Last().Item1<it.Item1?(curr.Last().Item2<it.Item1?curr.Add(it):curr.Last().Item2<it.Item2?curr.RemoveAt(curr.Count-1).Add((curr.Last().Item1,it.Item2)):curr):curr.Last().Item2<it.Item2?curr.RemoveAt(curr.Count-1).Add(it):curr)).First().Select(t => t.Item2-t.Item1+1).Sum());